#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;
    int n = s1.size();

    // dp[i][c1][c2] for horizontal type: last column had top color c1, bottom color c2
    // dp[i][c] for vertical type: last column had color c
    // We'll compress states.

    // We parse the grid into block types
    vector<int> block(n);
    for (int i = 0; i < n; i++) {
        if (s1[i] == s2[i]) block[i] = 1; // vertical domino
        else block[i] = 2; // two horizontal dominoes in this column
    }

    // dp0: for vertical, dp1 for horizontal
    // colors: 0,1,2
    if (block[0] == 1) {
        // vertical
        long long dp[3] = {1,1,1};
        for (int i = 1; i < n; i++) {
            long long ndp[3] = {0,0,0};
            if (block[i] == 1) {
                for (int c = 0; c < 3; c++) {
                    for (int nc = 0; nc < 3; nc++) {
                        if (nc != c) {
                            ndp[nc] = (ndp[nc] + dp[c]) % MOD;
                        }
                    }
                }
            } else {
                // two horizontal dominoes: top and bottom colors must be different from each other and from previous vertical color
                for (int c = 0; c < 3; c++) {
                    for (int t = 0; t < 3; t++) {
                        if (t == c) continue;
                        for (int b = 0; b < 3; b++) {
                            if (b == c || b == t) continue;
                            ndp[0] = (ndp[0] + dp[c]) % MOD; // we store as a single combined state for horizontal
                        }
                    }
                }
                // Actually better: store horizontal state as (top, bottom) pair
            }
            for (int c = 0; c < 3; c++) dp[c] = ndp[c];
        }
        long long ans = 0;
        for (int c = 0; c < 3; c++) ans = (ans + dp[c]) % MOD;
        cout << ans << "\n";
        return 0;
    } else {
        // first block horizontal
        // state: pair (top, bottom) with top != bottom
        map<pair<int,int>, long long> dp;
        for (int t = 0; t < 3; t++)
            for (int b = 0; b < 3; b++)
                if (t != b) dp[{t,b}] = 1;

        for (int i = 1; i < n; i++) {
            map<pair<int,int>, long long> ndp;
            if (block[i] == 1) {
                // vertical domino
                for (auto &[prev, ways] : dp) {
                    int pt = prev.first, pb = prev.second;
                    for (int c = 0; c < 3; c++) {
                        if (c != pt && c != pb) {
                            ndp[{c,c}] = (ndp[{c,c}] + ways) % MOD; // vertical stored as same top/bottom
                        }
                    }
                }
            } else {
                // two horizontals
                for (auto &[prev, ways] : dp) {
                    int pt = prev.first, pb = prev.second;
                    for (int t = 0; t < 3; t++) {
                        if (t == pt) continue;
                        for (int b = 0; b < 3; b++) {
                            if (b == pb || b == t) continue;
                            ndp[{t,b}] = (ndp[{t,b}] + ways) % MOD;
                        }
                    }
                }
            }
            dp = move(ndp);
        }
        long long ans = 0;
        for (auto &[_, ways] : dp) ans = (ans + ways) % MOD;
        cout << ans << "\n";
    }
    return 0;
}

