        if (i == 0) {
            if (cur == 0) ans = 3;
            else ans = 6;
        } else {
            if (prev == 0 && cur == 0) {
                ans = ans * 2 % MOD;
            } else if (prev == 0 && cur == 1) {
                ans = ans * 2 % MOD;
            } else if (prev == 1 && cur == 0) {
                ans = ans * 1 % MOD;
            } else { // prev == 1 && cur == 1
                ans = ans * 3 % MOD;
            }
        }

        prev = cur;
        if (cur == 0) i += 1;
        else i += 2;
    }

    cout << ans % MOD << '\n';
    return 0;
